from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        if not members:
            raise ValueError("Group must have at least one member")
        if len(set(members)) != len(members):
            raise ValueError("Member names must be unique")
        self._members: list[str] = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be positive")

        if payer not in self._balances:
            raise ValueError(f"Unknown member: {payer}")

        if participants is None:
            participants = list(self._members)
        else:
            participants = list(participants)
            if not participants:
                raise ValueError("Participants list must not be empty")
            for p in participants:
                if p not in self._balances:
                    raise ValueError(f"Unknown participant: {p}")

        total_cents = int(round(amount * 100))
        if total_cents <= 0:
            raise ValueError("Amount must be positive")

        n = len(participants)

        if n == 1:
            # Single participant: they bear the entire cost themselves.
            # Payer paid it, participant consumes it — net zero if same person.
            self._balances[payer] += amount
            self._balances[participants[0]] -= amount
            return

        # Equal split rounding down; leftover borne by payer.
        share_cents = total_cents // n
        # Sum of rounded-down shares:
        distributed = share_cents * n
        # Payer's own portion is rounded-down too; the payer absorbs remainder.
        # Every other participant owes exactly floor share.

        for p in participants:
            if p == payer:
                # Payer's own cost = total - (n-1)*floor_share
                payer_cost_cents = total_cents - share_cents * (n - 1)
                payer_cost = payer_cost_cents / 100.0
                self._balances[payer] += amount - payer_cost  # amount paid minus own cost
            else:
                self._balances[p] -= share_cents / 100.0

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: round(v, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Work in cents to avoid float issues.
        cents = {m: int(round(v * 100)) for m, v in self._balances.items()}

        debtors = [(m, -c) for m, c in cents.items() if c < 0]
        creditors = [(m, c) for m, c in cents.items() if c > 0]
        debtors.sort(key=lambda x: -x[1])
        creditors.sort(key=lambda x: -x[1])

        payments: list[tuple[str, str, float]] = []

        i = j = 0
        while i < len(debtors) and j < len(creditors):
            d_name, d_amt = debtors[i]
            c_name, c_amt = creditors[j]

            pay = min(d_amt, c_amt)
            if pay >= 100:
                payments.append((d_name, c_name, pay / 100.0))

            debtors[i] = (d_name, d_amt - pay)
            creditors[j] = (c_name, c_amt - pay)

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return payments
